-- Exact3 root-only read checkpoint; no execution by the preparer.
BEGIN READ ONLY;
SET LOCAL statement_timeout='20s';
SELECT 'printings' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM catalog.card_printings t WHERE id=any(ARRAY['f732147f-deef-4c65-a092-4ed2e7bbfcad'::uuid,'58053385-0e6d-45a1-b7aa-ba11abe75091'::uuid,'99246359-6f35-43db-9f85-2ccca99bceec'::uuid]::uuid[]) ORDER BY identity LIMIT 4;
SELECT 'variants' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM catalog.card_variants t WHERE printing_id=any(ARRAY['f732147f-deef-4c65-a092-4ed2e7bbfcad'::uuid,'58053385-0e6d-45a1-b7aa-ba11abe75091'::uuid,'99246359-6f35-43db-9f85-2ccca99bceec'::uuid]::uuid[]) ORDER BY identity LIMIT 4;
SELECT 'names' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM catalog.card_names t WHERE printing_id=any(ARRAY['f732147f-deef-4c65-a092-4ed2e7bbfcad'::uuid,'58053385-0e6d-45a1-b7aa-ba11abe75091'::uuid,'99246359-6f35-43db-9f85-2ccca99bceec'::uuid]::uuid[]) ORDER BY identity LIMIT 7;
SELECT 'sets' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM catalog.sets t WHERE id=any(ARRAY['c24a6f11-2b12-4dbd-8d50-61f17e8e6a4f'::uuid]::uuid[]) ORDER BY identity LIMIT 2;
SELECT 'assets' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM catalog.assets t WHERE printing_id=any(ARRAY['f732147f-deef-4c65-a092-4ed2e7bbfcad'::uuid,'58053385-0e6d-45a1-b7aa-ba11abe75091'::uuid,'99246359-6f35-43db-9f85-2ccca99bceec'::uuid]::uuid[]) OR variant_id=any(ARRAY['41b979bb-0d07-4b9e-bf3f-04de506c2831'::uuid,'4a752b13-fdf9-4b5a-a94b-8964e50a2ad3'::uuid,'96320f61-2e8c-4145-8fbc-7c5f43eeba5c'::uuid]::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id=any(ARRAY['c24a6f11-2b12-4dbd-8d50-61f17e8e6a4f'::uuid]::uuid[])) ORDER BY identity LIMIT 201;
SELECT 'links' AS scope,catalogue_version_id::text||':'||asset_id::text AS identity,to_jsonb(t) AS payload FROM catalog.catalogue_version_assets t WHERE (printing_id=any(ARRAY['f732147f-deef-4c65-a092-4ed2e7bbfcad'::uuid,'58053385-0e6d-45a1-b7aa-ba11abe75091'::uuid,'99246359-6f35-43db-9f85-2ccca99bceec'::uuid]::uuid[]) OR variant_id=any(ARRAY['41b979bb-0d07-4b9e-bf3f-04de506c2831'::uuid,'4a752b13-fdf9-4b5a-a94b-8964e50a2ad3'::uuid,'96320f61-2e8c-4145-8fbc-7c5f43eeba5c'::uuid]::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id=any(ARRAY['c24a6f11-2b12-4dbd-8d50-61f17e8e6a4f'::uuid]::uuid[]))) OR asset_id IN (SELECT id FROM catalog.assets WHERE printing_id=any(ARRAY['f732147f-deef-4c65-a092-4ed2e7bbfcad'::uuid,'58053385-0e6d-45a1-b7aa-ba11abe75091'::uuid,'99246359-6f35-43db-9f85-2ccca99bceec'::uuid]::uuid[]) OR variant_id=any(ARRAY['41b979bb-0d07-4b9e-bf3f-04de506c2831'::uuid,'4a752b13-fdf9-4b5a-a94b-8964e50a2ad3'::uuid,'96320f61-2e8c-4145-8fbc-7c5f43eeba5c'::uuid]::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id=any(ARRAY['c24a6f11-2b12-4dbd-8d50-61f17e8e6a4f'::uuid]::uuid[]))) ORDER BY identity LIMIT 201;
SELECT 'sources' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM ingest.sources t WHERE code=any(ARRAY['scrydex','pokellector','tcgcollector']::text[]) OR base_url ilike any(ARRAY['%scrydex.com%','%pokellector.com%','%tcgcollector.com%']) ORDER BY identity LIMIT 4;
ROLLBACK;
